$d = $argv[1] ?? ''; if ($d === '') { fwrite(STDERR, "usage: kicad_fixture.php OUTDIR\n"); exit(2); } @mkdir($d, 0775, true);
function block(string $t, int $start): string { $depth = 0; $n = strlen($t); for ($i = $start; $i < $n; $i++) { if ($t[$i] === '"') { while ($i + 1 < $n && $t[++$i] !== '"') if ($t[$i] === '\\') $i++; continue; } if ($t[$i] === '(') $depth++; elseif ($t[$i] === ')') { $depth--; if ($depth === 0) return substr($t, $start, $i - $start + 1); } } return ''; }
$sym = ''; foreach (['/usr/share/kicad/symbols/Device.kicad_sym'] as $f) if (is_file($f)) { $t = file_get_contents($f); $p = strpos($t, "(symbol \"R\""); if ($p !== false) $sym = preg_replace('/^\(symbol "R"/', '(symbol "Device:R"', block($t, $p)); }
if ($sym === '') $sym = '(symbol "Device:R" (pin_numbers hide) (pin_names (offset 0)) (in_bom yes) (on_board yes) (property "Reference" "R" (at 2 0 90) (effects (font (size 1.27 1.27)))) (property "Value" "R" (at -2 0 90) (effects (font (size 1.27 1.27)))) (symbol "R_0_1" (rectangle (start -1.016 -2.54) (end 1.016 2.54) (stroke (width 0.254) (type default)) (fill (type none)))) (symbol "R_1_1" (pin passive line (at 0 3.81 270) (length 1.27) (name "~" (effects (font (size 1.27 1.27)))) (number "1" (effects (font (size 1.27 1.27))))) (pin passive line (at 0 -3.81 90) (length 1.27) (name "~" (effects (font (size 1.27 1.27)))) (number "2" (effects (font (size 1.27 1.27)))))))';
$uuid = fn($n) => sprintf('00000000-0000-4000-8000-%012d', $n);
$part = function (int $n, string $ref, string $val, string $fp, int $x) use ($uuid) { return "  (symbol (lib_id \"Device:R\") (at $x 50 0) (unit 1) (in_bom yes) (on_board yes) (dnp no) (uuid \"" . $uuid($n) . "\")\n    (property \"Reference\" \"$ref\" (at " . ($x + 2) . " 49 0) (effects (font (size 1.27 1.27)) (justify left)))\n    (property \"Value\" \"$val\" (at " . ($x + 2) . " 51 0) (effects (font (size 1.27 1.27)) (justify left)))\n    (property \"Footprint\" \"$fp\" (at $x 50 0) (effects (font (size 1.27 1.27)) hide))\n    (pin \"1\" (uuid \"" . $uuid($n + 100) . "\")) (pin \"2\" (uuid \"" . $uuid($n + 200) . "\"))\n    (instances (project \"t\" (path \"/" . $uuid(1) . "\" (reference \"$ref\") (unit 1))))\n  )\n"; };
$sch = function (string $parts, string $labels) use ($sym, $uuid) { return "(kicad_sch (version 20230121) (generator eeschema)\n  (uuid \"" . $uuid(1) . "\")\n  (paper \"A4\")\n  (lib_symbols\n    $sym\n  )\n$parts$labels  (sheet_instances (path \"/\" (page \"1\")))\n)\n"; };
$FP = 'Resistor_SMD:R_0805_2012Metric';
file_put_contents("$d/good.kicad_sch", $sch($part(10, 'R1', '10k', $FP, 100) . $part(11, 'R2', '10k', $FP, 120) . $part(12, 'R3', '4k7', $FP, 140), "  (label \"NET1\" (at 100 40 0) (effects (font (size 1.27 1.27))) (uuid \"" . $uuid(30) . "\"))\n  (label \"NET1\" (at 120 40 0) (effects (font (size 1.27 1.27))) (uuid \"" . $uuid(31) . "\"))\n  (wire (pts (xy 100 46.19) (xy 120 46.19)) (stroke (width 0) (type default)) (uuid \"" . $uuid(32) . "\"))\n"));
file_put_contents("$d/bad.kicad_sch", $sch($part(10, 'R1', '10k', $FP, 100) . $part(11, 'R1', '10k', $FP, 120) . $part(12, 'R?', '', '', 140) . $part(13, 'R4', '~', '', 160), "  (label \"LONELY\" (at 100 40 0) (effects (font (size 1.27 1.27))) (uuid \"" . $uuid(30) . "\"))\n"));
$layers = '(layers (0 "F.Cu" signal) (31 "B.Cu" signal) (32 "B.Adhes" user "B.Adhesive") (33 "F.Adhes" user "F.Adhesive") (34 "B.Paste" user) (35 "F.Paste" user) (36 "B.SilkS" user "B.Silkscreen") (37 "F.SilkS" user "F.Silkscreen") (38 "B.Mask" user) (39 "F.Mask" user) (44 "Edge.Cuts" user) (45 "Margin" user) (46 "B.CrtYd" user "B.Courtyard") (47 "F.CrtYd" user "F.Courtyard") (48 "B.Fab" user) (49 "F.Fab" user))';
$fpd = fn(string $ref, string $val, float $x, float $y, int $n) => "  (footprint \"$FP\" (layer \"F.Cu\") (tstamp \"" . $uuid($n) . "\") (at $x $y)\n    (fp_text reference \"$ref\" (at 0 -1.65) (layer \"F.SilkS\") (effects (font (size 1 1) (thickness 0.15))) (tstamp \"" . $uuid($n + 50) . "\"))\n    (fp_text value \"$val\" (at 0 1.65) (layer \"F.Fab\") (effects (font (size 1 1) (thickness 0.15))) (tstamp \"" . $uuid($n + 60) . "\"))\n    (pad \"1\" smd roundrect (at -0.9125 0) (size 1.025 1.4) (layers \"F.Cu\" \"F.Paste\" \"F.Mask\") (roundrect_rratio 0.243902) (net 1 \"GND\") (tstamp \"" . $uuid($n + 70) . "\"))\n    (pad \"2\" smd roundrect (at 0.9125 0) (size 1.025 1.4) (layers \"F.Cu\" \"F.Paste\" \"F.Mask\") (roundrect_rratio 0.243902) (net 2 \"VCC\") (tstamp \"" . $uuid($n + 80) . "\"))\n  )\n";
$pcb = fn(string $body) => "(kicad_pcb (version 20221018) (generator pcbnew)\n  (general (thickness 1.6))\n  (paper \"A4\")\n  $layers\n  (setup (pad_to_mask_clearance 0))\n  (net 0 \"\") (net 1 \"GND\") (net 2 \"VCC\")\n$body)\n";
file_put_contents("$d/good.kicad_pcb", $pcb($fpd('R1', '10k', 20, 20, 10) . $fpd('R2', '10k', 30, 20, 11) . "  (gr_rect (start 10 10) (end 50 40) (stroke (width 0.1) (type default)) (fill none) (layer \"Edge.Cuts\") (tstamp \"" . $uuid(90) . "\"))\n  (segment (start 19.0875 20) (end 29.0875 20) (width 0.25) (layer \"F.Cu\") (net 1) (tstamp \"" . $uuid(91) . "\"))\n  (via (at 25 25) (size 0.8) (drill 0.4) (layers \"F.Cu\" \"B.Cu\") (net 1) (tstamp \"" . $uuid(92) . "\"))\n"));
file_put_contents("$d/bad.kicad_pcb", $pcb($fpd('R1', '10k', 20, 20, 10) . $fpd('R1', '10k', 90, 90, 11) . "  (segment (start 19 20) (end 29 20) (width 0.1) (layer \"F.Cu\") (net 1) (tstamp \"" . $uuid(91) . "\"))\n  (via (at 25 25) (size 0.4) (drill 0.15) (layers \"F.Cu\" \"B.Cu\") (net 1) (tstamp \"" . $uuid(92) . "\"))\n"));
file_put_contents("$d/outside.kicad_pcb", $pcb($fpd('R1', '10k', 20, 20, 10) . $fpd('R2', '10k', 90, 90, 11) . "  (gr_rect (start 10 10) (end 50 40) (stroke (width 0.1) (type default)) (fill none) (layer \"Edge.Cuts\") (tstamp \"" . $uuid(90) . "\"))\n"));
file_put_contents("$d/broken.kicad_sch", "(kicad_sch (version 20230121) (generator eeschema\n  (uuid \"x\"\n"); echo "wrote $d\n";
